// Project library: metadata queries never load the document bodies.
const projectDocumentDB=new Promise((resolve,reject)=>{const r=indexedDB.open('forja-project-documents',1);r.onupgradeneeded=()=>{const meta=r.result.createObjectStore('documents',{keyPath:'id'});meta.createIndex('projectId','projectId');r.result.createObjectStore('bodies',{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});projectDocumentDB.catch(()=>{});
async function documentRead(store,key,index){const db=await projectDocumentDB;return new Promise((resolve,reject)=>{const tx=db.transaction(store,'readonly'),source=index?tx.objectStore(store).index(index):tx.objectStore(store),r=index?source.getAll(key):source.get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function documentSave(metadata,blob){const db=await projectDocumentDB;return new Promise((resolve,reject)=>{const tx=db.transaction(blob?['documents','bodies']:['documents'],'readwrite');tx.objectStore('documents').put(metadata);if(blob)tx.objectStore('bodies').put({id:metadata.id,blob});tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const documentCategories=['Documento','Contrato','Plano','Permiso','Acta','Informe','Otro'];
const documentsSection=document.createElement('section');documentsSection.id='documentsSection';costSection.after(documentsSection);
const documentDialog=document.createElement('dialog');documentDialog.id='documentDialog';document.body.append(documentDialog);
const documentPreview=document.createElement('dialog');documentPreview.id='documentPreview';document.body.append(documentPreview);
let documentsCache=[],documentsGeneration=0,documentsProject=null,documentsTrash=false,documentPreviewURL=null;
function documentSize(bytes){return bytes<1024*1024?(bytes/1024).toFixed(1)+' KB':(bytes/1024/1024).toFixed(1)+' MB'}
async function drawDocuments(){
 const generation=++documentsGeneration,p=data.projects.find(p=>p.id===selected);documentsSection.hidden=!p||projectPanel!=='documents';if(!p)return;
 const tabs=$('#scheduleSection .projectPanels');if(tabs&&!tabs.querySelector('[data-panel="documents"]'))tabs.insertAdjacentHTML('beforeend',`<button data-panel="documents" class="${projectPanel==='documents'?'primary':''}">Documentos</button>`);
 if(projectPanel!=='documents')return;if(documentsProject!==p.id){documentsProject=p.id;documentsTrash=false}documentsCache=[];
 documentsSection.innerHTML=`<div class="sectionhead"><div><h2>Documentos del proyecto</h2><p class="muted">Contratos, planos y archivos importantes, en un solo lugar.</p></div><button class="primary" id="addProjectDocument">＋ Añadir documento</button></div><div class="documentNotice">Guardado en este navegador y dispositivo. Descarga tus archivos para conservar una copia; no se sincronizan entre equipos.</div><div class="documentFilters"><input id="documentSearch" type="search" aria-label="Buscar documentos" placeholder="Buscar por título, archivo o notas…"><select id="documentCategoryFilter" aria-label="Filtrar categoría de documentos"><option value="">Todas las categorías</option>${documentCategories.map(x=>`<option>${x}</option>`).join('')}</select><label class="documentCheck"><input id="documentImportantFilter" type="checkbox"> Solo importantes</label><button id="documentTrashToggle">${documentsTrash?'← Volver a documentos':'Papelera'}</button></div><p class="muted" id="documentSummary" role="status">Cargando documentos…</p><div id="documentList" class="documentGrid"></div>`;
 $('#documentSearch').oninput=renderDocumentList;$('#documentCategoryFilter').onchange=renderDocumentList;$('#documentImportantFilter').onchange=renderDocumentList;
 try{const rows=await documentRead('documents',p.id,'projectId');if(generation!==documentsGeneration)return;documentsCache=rows;renderDocumentList()}catch{if(generation!==documentsGeneration)return;$('#documentSummary').textContent='No se pudo acceder al almacenamiento local. Revisa los permisos o el espacio del navegador.'}
}
function renderDocumentList(){if(!$('#documentList'))return;const search=$('#documentSearch').value.trim().toLocaleLowerCase(),category=$('#documentCategoryFilter').value,important=$('#documentImportantFilter').checked;
 const all=documentsCache.filter(d=>Boolean(d.trashedAt)===documentsTrash),rows=all.filter(d=>(!category||d.category===category)&&(!important||d.important)&&[d.title,d.fileName,d.notes].join(' ').toLocaleLowerCase().includes(search)).sort((a,b)=>Number(b.important)-Number(a.important)||b.updatedAt-a.updatedAt);
 $('#documentSummary').textContent=(documentsTrash?'Papelera · ':'')+rows.length+' de '+all.length+' archivo(s) · '+documentSize(all.reduce((n,d)=>n+d.size,0));
 $('#documentList').innerHTML=rows.map(d=>`<article class="documentCard"><div class="documentCardTop"><span class="documentFileIcon">${esc(d.fileName.split('.').length>1?d.fileName.split('.').pop().slice(0,6).toUpperCase():'ARCH')}</span><span class="badge">${esc(d.category)}</span>${d.important?'<span class="documentStar" title="Importante">★</span>':''}</div><h3>${esc(d.title)}</h3><p class="documentOriginal">${esc(d.fileName)}</p><p class="documentNotes">${esc(d.notes||'Sin notas adicionales.')}</p><div class="documentMeta"><span>${documentSize(d.size)}</span><span>${d.documentDate?date(d.documentDate):'Sin fecha documental'}</span></div><small class="documentSaved">Añadido: ${new Date(d.createdAt).toLocaleDateString('es')}</small><div class="documentActions">${documentsTrash?`<button data-document-restore="${d.id}">Restaurar</button>`:`<button data-document-edit="${d.id}">Editar</button>${documentCanPreview(d)?`<button data-document-preview="${d.id}">Ver</button>`:''}<button data-document-trash="${d.id}">Papelera</button>`}<button data-document-download="${d.id}">↓ Descargar</button></div></article>`).join('')||`<div class="documentEmpty"><span>▤</span><h3>${all.length?'No hay coincidencias':documentsTrash?'La papelera está vacía':'El archivo de tu proyecto empieza aquí'}</h3><p>${all.length?'Prueba otra búsqueda o categoría.':documentsTrash?'Los documentos enviados a la papelera se pueden restaurar.':'Añade contratos, documentos y archivos importantes con sus notas y fechas.'}</p>${!all.length&&!documentsTrash?'<button class="primary" id="emptyAddDocument">＋ Añadir documento</button>':''}</div>`;
}
function documentCanPreview(d){return ['application/pdf','image/jpeg','image/png','image/webp','image/gif','text/plain'].includes(d.type)}
const drawBeforeDocuments=drawSchedule;drawSchedule=function(){drawBeforeDocuments();drawDocuments()};drawSchedule();
function openDocumentEditor(id){const pid=selected,existing=id?documentsCache.find(d=>d.id===id):null;if(id&&!existing)return;
 documentDialog.innerHTML=`<form id="projectDocumentForm"><div class="sectionhead"><h2>${existing?'Editar documento':'Añadir documento'}</h2><button type="button" id="closeDocumentEditor" aria-label="Cerrar documento">✕</button></div><label>Título<input name="title" required maxlength="160" value="${esc(existing?.title)}" placeholder="Ej. Contrato de ejecución de obra"></label><label>Categoría<select name="category">${documentCategories.map(x=>`<option ${x===(existing?.category||'Documento')?'selected':''}>${x}</option>`).join('')}</select></label><label>Fecha del documento<input name="documentDate" type="date" value="${esc(existing?.documentDate)}"></label><label>Notas<textarea name="notes" maxlength="3000" rows="3" placeholder="Alcance, referencia, versión o información relevante…">${esc(existing?.notes)}</textarea></label><label class="documentCheck"><input name="important" type="checkbox" ${existing?.important?'checked':''}> Marcar como importante</label><label class="documentUpload">${existing?'Reemplazar archivo (opcional)':'Archivo'}<input name="file" type="file" ${existing?'':'required'}></label><p class="muted">Hasta 50 MB por archivo. PDF, Office, imágenes, planos y otros formatos. ${existing?'Actual: '+esc(existing.fileName)+'. Reemplazarlo sobrescribe la copia anterior.':''}</p><div class="dialogfoot"><button type="button" id="cancelDocumentEditor">Cancelar</button><button type="submit" class="primary" id="saveProjectDocument">Guardar documento</button></div><p id="documentFormError" class="documentError" role="alert"></p></form>`;
 $('#closeDocumentEditor').onclick=$('#cancelDocumentEditor').onclick=()=>documentDialog.close();
 $('#projectDocumentForm').onsubmit=async e=>{e.preventDefault();const f=e.target.elements,file=f.file.files[0],error=$('#documentFormError'),button=$('#saveProjectDocument');error.textContent='';const title=f.title.value.trim();if(!title){error.textContent='Escribe un título para el documento.';return}if(!existing&&!file){error.textContent='Selecciona un archivo.';return}if(file&&file.size>50*1024*1024){error.textContent='El archivo supera el máximo de 50 MB.';return}if(file&&existing&&!confirm('¿Reemplazar el archivo actual? La copia anterior no se conservará.'))return;button.disabled=true;
 try{const d={...(existing||{}),id:existing?.id||crypto.randomUUID(),projectId:pid,title,category:f.category.value,documentDate:f.documentDate.value,notes:f.notes.value.trim(),important:f.important.checked,createdAt:existing?.createdAt||Date.now(),updatedAt:Date.now(),trashedAt:null};if(file)Object.assign(d,{fileName:file.name,type:file.type,size:file.size});await documentSave(d,file);documentDialog.close();toast('Documento guardado');if(selected===pid)drawDocuments()}catch{error.textContent='No se pudo guardar. Revisa el espacio y los permisos del navegador.';button.disabled=false}};
 documentDialog.showModal();
}
async function previewDocument(id){const d=documentsCache.find(d=>d.id===id);if(!d||!documentCanPreview(d))return;try{const body=await documentRead('bodies',id);if(!body?.blob)throw new Error();documentPreview.innerHTML=`<div class="sectionhead"><h2>${esc(d.title)}</h2><button id="closeDocumentPreview" aria-label="Cerrar vista previa">✕</button></div><div id="documentPreviewBody"></div>`;$('#closeDocumentPreview').onclick=()=>documentPreview.close();documentPreviewURL=URL.createObjectURL(body.blob);const container=$('#documentPreviewBody');if(d.type==='text/plain'){const pre=document.createElement('pre');pre.textContent=await body.blob.text();container.append(pre)}else if(d.type==='application/pdf'){const frame=document.createElement('iframe');frame.src=documentPreviewURL;frame.title=d.title;container.append(frame);const hint=document.createElement('p');hint.className='muted';hint.textContent='Si el navegador no muestra el PDF, descárgalo desde la tarjeta del documento.';container.append(hint)}else{const img=document.createElement('img');img.src=documentPreviewURL;img.alt=d.title;container.append(img)}documentPreview.showModal()}catch{toast('No se pudo abrir el documento.')}}
documentPreview.addEventListener('close',()=>{if(documentPreviewURL)URL.revokeObjectURL(documentPreviewURL);documentPreviewURL=null;documentPreview.innerHTML=''});
documentsSection.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(['addProjectDocument','emptyAddDocument'].includes(b.id)){openDocumentEditor();return}if(b.id==='documentTrashToggle'){documentsTrash=!documentsTrash;drawDocuments();return}if(b.dataset.documentEdit){openDocumentEditor(b.dataset.documentEdit);return}if(b.dataset.documentPreview){previewDocument(b.dataset.documentPreview);return}
 const id=b.dataset.documentDownload||b.dataset.documentTrash||b.dataset.documentRestore,d=documentsCache.find(x=>x.id===id);if(!d)return;b.disabled=true;try{if(b.dataset.documentDownload){const body=await documentRead('bodies',id);if(!body?.blob)throw new Error();const url=URL.createObjectURL(body.blob),a=document.createElement('a');a.href=url;a.download=d.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}else{await documentSave({...d,trashedAt:b.dataset.documentTrash?Date.now():null,updatedAt:Date.now()});toast(b.dataset.documentTrash?'Documento movido a la papelera':'Documento restaurado');drawDocuments()}}catch{toast('No se pudo completar la operación. Comprueba el almacenamiento local.')}finally{b.disabled=false}});

